<template><div><div class="page-head"><div><h2>智能推荐策略</h2><p>线上策略 {{config.strategy||'intent-first-interest-goal-v2'}}</p></div><el-button type="primary" :loading="saving" @click="save">发布策略</el-button></div><el-alert title="兴趣与学习目标应保持主导；水平仅作为轻量适配信号。" type="info" :closable="false"/><el-card shadow="never" class="config"><div v-for="item in items" :key="item.key" class="weight"><div><strong>{{item.name}}</strong><small>{{item.tip}}</small></div><el-slider v-model="config[item.key]" :min="0" :max="50" show-input/></div><el-divider/><div class="total">基础权重合计 <el-tag :type="total===100?'success':'danger'">{{total}}%</el-tag></div><div class="weight"><div><strong>水平匹配额外加分</strong><small>不计入基础权重，只用于相近课程间排序</small></div><el-slider v-model="config.levelBonus" :min="0" :max="10" show-input/></div></el-card></div></template>
<script setup>import{reactive,computed,onMounted,ref}from'vue';import{adminApi}from'@/api/admin';import{ElMessage}from'element-plus';const saving=ref(false),config=reactive({interest:36,goal:34,profile:12,popularity:10,quality:8,levelBonus:3});const items=[{key:'interest',name:'学习兴趣',tip:'课程主题与兴趣的语义相关度'},{key:'goal',name:'学习目标',tip:'课程内容对目标达成的帮助程度'},{key:'profile',name:'历史偏好',tip:'收藏、购买、学习和评分行为'},{key:'popularity',name:'课程热度',tip:'平台学员数量'},{key:'quality',name:'课程质量',tip:'课程综合评分'}];const total=computed(()=>items.reduce((n,i)=>n+config[i.key],0));async function save(){if(total.value!==100)return ElMessage.error('基础权重合计必须为 100%');saving.value=true;try{await adminApi.updateRecommendationConfig(config);ElMessage.success('推荐策略已发布并立即生效')}finally{saving.value=false}}onMounted(async()=>{const r=await adminApi.getRecommendationConfig();Object.assign(config,r.data||{})})</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head h2{margin:0}.page-head p,small{color:#909399}.config{margin-top:18px;max-width:900px}.weight{display:grid;grid-template-columns:260px 1fr;gap:30px;align-items:center;padding:14px}.weight small{display:block;margin-top:5px}.total{text-align:right;font-weight:600}</style>
